            mesh_key: key.mesh_key,
            bind_group_data: key.bind_group_data.base,
        };

        B::specialize(pipeline, descriptor, layout, base_key)?;

        let extension_key = Material2dKey {
            mesh_key: key.mesh_key,
            bind_group_data: key.bind_group_data.extension,
