pub fn check_views_need_specialization(
    mut view_key_cache: ResMut<ViewKeyCache>,
    mut dirty_specializations: ResMut<DirtySpecializations>,
    mut dirty_wireframe_specializations: ResMut<DirtyWireframeSpecializations>,
    cameras: Query<(
        &MainEntity,
        &ExtractedView,
        &ExtractedCamera,
        &Msaa,
        Option<&Tonemapping>,
        Option<&DebandDither>,
        Option<&ResolvedCompositingSpace>,
    )>,
) {
    for (view_entity, view, camera, msaa, tonemapping, dither, resolved_space) in &cameras {
        let mut view_key = Mesh2dPipelineKey::from_msaa_samples(msaa.samples())
            | Mesh2dPipelineKey::from_target_format(view.target_format)
            | Mesh2dPipelineKey::from_compositing_space(ResolvedCompositingSpace::space(
                resolved_space,
            ));

        if camera.tonemap_in_shader
            && let Some(tonemapping) = tonemapping
        {
            view_key |= Mesh2dPipelineKey::TONEMAP_IN_SHADER;
            view_key |= tonemapping_pipeline_key(*tonemapping);
            if let Some(DebandDither::Enabled) = dither {
                view_key |= Mesh2dPipelineKey::DEBAND_DITHER;
            }
        }

        if !view_key_cache
            .get_mut(view_entity)
            .is_some_and(|current_key| *current_key == view_key)
        {
            view_key_cache.insert(*view_entity, view_key);
            dirty_specializations
                .views
                .insert(view.retained_view_entity);
            dirty_wireframe_specializations
                .views
                .insert(view.retained_view_entity);
        }
    }
