item.aggregated_output:
  1	//! 2D lighting for sprites and 2D meshes.
  2	//!
  3	//! The lighting model is forward rendered. Sprites and [`ColorMaterial`] meshes
  4	//! use their normal maps directly in their fragment shaders, so no extra lighting
  5	//! render pass or camera is required. Lights are additive and shadows are
  6	//! calculated from [`LightOccluder2d`] line segments.
  7	//!
  8	//! [`ColorMaterial`]: crate::ColorMaterial
  9	
 10	use bevy_app::{App, Plugin};
 11	use bevy_color::{Color, LinearRgba};
 12	use bevy_ecs::prelude::*;
 13	use bevy_ecs::schedule::IntoScheduleConfigs;
 14	use bevy_math::{UVec4, Vec2, Vec4};
 15	use bevy_reflect::prelude::*;
 16	use bevy_render::{
 17	    render_resource::{ShaderType, UniformBuffer},
 18	    renderer::{RenderDevice, RenderQueue},
 19	    Extract, ExtractSchedule, Render, RenderApp, RenderSystems,
 20	};
 21	use bevy_shader::load_shader_library;
 22	use bevy_transform::components::{GlobalTransform, Transform};
 23	
 24	/// The maximum number of [`PointLight2d`]s that can affect a 2D view.
 25	pub const MAX_LIGHTS_2D: usize = 32;
 26	
 27	/// The maximum number of shadow-casting line segments in a 2D view.
 28	pub const MAX_LIGHT_OCCLUDER_SEGMENTS_2D: usize = 128;
 29	
 30	/// A point light for 2D scenes.
 31	///
 32	/// Add a [`Transform`] to position the light. Any number of lights can affect
 33	/// the same sprite or mesh, up to [`MAX_LIGHTS_2D`].
 34	///
 35	/// ```
 36	/// # use bevy_ecs::prelude::*;
 37	/// # use bevy_sprite_render::PointLight2d;
 38	/// # use bevy_transform::components::Transform;
 39	/// # use bevy_color::palettes::css::ORANGE;
 40	/// # fn setup(mut commands: Commands) {
 41	/// commands.spawn((
 42	///     PointLight2d {
 43	///         color: ORANGE.into(),
 44	///         intensity: 1.5,
 45	///         range: 400.0,
 46	///         ..Default::default()
 47	///     },
 48	///     Transform::from_xyz(100.0, 50.0, 0.0),
 49	/// ));
 50	/// # }
 51	/// ```
 52	#[derive(Component, Debug, Clone, Copy, Reflect)]
 53	#[reflect(Component, Default, Debug, Clone)]
 54	#[require(Transform)]
 55	pub struct PointLight2d {
 56	    /// The color of the light.
 57	    pub color: Color,
 58	    /// The brightness multiplier applied to [`PointLight2d::color`].
 59	    pub intensity: f32,
 60	    /// The maximum distance at which the light contributes.
 61	    pub range: f32,
 62	    /// The height of the light above the 2D plane.
 63	    ///
 64	    /// This controls the direction of the light relative to surface normals.
 65	    /// Larger values make normal-mapped surfaces face the light more directly.
 66	    pub height: f32,
 67	    /// Whether this light is blocked by [`LightOccluder2d`]s.
 68	    pub shadows_enabled: bool,
 69	}
 70	
 71	impl Default for PointLight2d {
 72	    fn default() -> Self {
 73	        Self {
 74	            color: Color::WHITE,
 75	            intensity: 1.0,
 76	            range: 200.0,
 77	            height: 100.0,
 78	            shadows_enabled: true,
 79	        }
 80	    }
 81	}
 82	
 83	/// Global ambient light for 2D scenes.
 84	///
 85	/// The default is white with a brightness of `1.0`, which keeps scenes without
 86	/// any [`PointLight2d`]s unchanged.
 87	#[derive(Resource, Debug, Clone, Reflect)]
 88	#[reflect(Resource, Default, Debug, Clone)]
 89	pub struct AmbientLight2d {
 90	    /// The ambient light color.
 91	    pub color: Color,
 92	    /// The brightness multiplier applied to [`AmbientLight2d::color`].
 93	    pub brightness: f32,
 94	}
 95	
 96	impl Default for AmbientLight2d {
 97	    fn default() -> Self {
 98	        Self {
 99	            color: Color::WHITE,
100	            brightness: 1.0,
101	        }
102	    }
103	}
104	
105	/// A polygonal 2D light occluder used to cast shadows.
106	///
107	/// The vertices are in the entity's local space. Consecutive vertices form line
108	/// segments, and if [`LightOccluder2d::closed`] is `true`, the last vertex is
109	/// connected back to the first one.
110	#[derive(Component, Debug, Clone, Reflect)]
111	#[reflect(Component, Default, Debug, Clone)]
112	#[require(Transform)]
113	pub struct LightOccluder2d {
114	    /// Vertices of the occluder polygon or polyline.
115	    pub vertices: Vec<Vec2>,
116	    /// Whether the last vertex connects back to the first vertex.
117	    pub closed: bool,
118	}
119	
120	impl Default for LightOccluder2d {
121	    fn default() -> Self {
122	        Self {
123	            vertices: Vec::new(),
124	            closed: true,
125	        }
126	    }
127	}
128	
129	impl LightOccluder2d {
130	    /// Creates a closed polygon occluder from a list of local-space vertices.
131	    pub fn polygon(vertices: impl Into<Vec<Vec2>>) -> Self {
132	        Self {
133	            vertices: vertices.into(),
134	            closed: true,
135	        }
136	    }
137	
138	    /// Creates an open polyline occluder from a list of local-space vertices.
139	    pub fn polyline(vertices: impl Into<Vec<Vec2>>) -> Self {
140	        Self {
141	            vertices: vertices.into(),
142	            closed: false,
143	        }
144	    }
145	
146	    /// Creates a rectangular occluder centered on the entity's origin.
147	    pub fn rectangle(half_extents: Vec2) -> Self {
148	        Self::polygon([
149	            Vec2::new(-half_extents.x, -half_extents.y),
150	            Vec2::new(half_extents.x, -half_extents.y),
151	            Vec2::new(half_extents.x, half_extents.y),
152	            Vec2::new(-half_extents.x, half_extents.y),
153	        ])
154	    }
155	}
156	
157	#[derive(Clone, Copy, Debug, Default, ShaderType)]
158	struct GpuPointLight2d {
159	    /// `xy` is the position, `z` is the range, and `w` is the intensity.
160	    position_range_intensity: Vec4,
161	    /// `rgb` is the color and `w` is reserved for future shadow parameters.
162	    color: Vec4,
163	    /// `x` is the light height and `y` indicates whether shadows are enabled.
164	    params: Vec4,
165	}
166	
167	/// GPU representation of all 2D lights for a view.
168	#[derive(Clone, Debug, ShaderType)]
169	pub(crate) struct Lighting2dUniform {
170	    /// `rgb` is the ambient color multiplied by its brightness.
171	    ambient: Vec4,
172	    /// `x` is the light count and `y` is the occluder segment count.
173	    counts: UVec4,
174	    lights: [GpuPointLight2d; MAX_LIGHTS_2D],
175	    occluders: [Vec4; MAX_LIGHT_OCCLUDER_SEGMENTS_2D],
176	}
177	
178	impl Default for Lighting2dUniform {
179	    fn default() -> Self {
